    let b = clone(a); // Clone 'a' to avoid ownership error
    print(len(a));
    print(len(b));
}

fn main() {
    let a = push(push(vec(), 1), 2);
    let b = a.clone();
    let c = a;
    print(len(b));
    print(len(c));
}

fn main() {
    let s = "ab";
    print(str_len(s));
    let total = 0;
    for i in range(0, 3) {
        let t = s.clone(); // Clone the string to avoid ownership issues
        total = total + str_len(t);
    }
    print(total);
}

fn main() {
    let mut v = push(push(vec(), 1), 2);
    print(len(v));
    for x in v {
        let mut temp = push(v, x);
        v = temp;
    }
    print(len(v));
}

