fn main() {
    let v = push(push(vec(), 1), 2)
    let b = Bag { items: clone(v), label: "hello" }
    print(len(clone(v)))
    print(str_len(b.label))
}

struct Reading { label: Str, values: Vec<Int> }

fn first_big(v: Vec<Int>) -> Int {
    let found = -1;
    for x in v {
        if x > 10 {
            found = x;
            break;
        }
    }
    found
}

fn second(v: Vec<Int>) -> Option<Int> {
    let x = get(v, 1)?;
    Some(x + 1)
}

fn main() {
    let r = Reading { label: "lab", values: push(push(vec(), 3), 42) };
    print(first_big(r.values));            // field access copies: r stays usable
    let v = push(push(vec(), 1), 2);
    let o = Some(v);
    print(len(v));
    print(size(o));
}

fn main() {
    let s = "hello"
    let v = push(push(vec(), "world"), clone(s))
    print(len(v))
    print(str_len(clone(s)))
}

struct Point { x: Int, tag: Str }

fn main() {
    let p = Point { x: 11, tag: "hello" }
    let q = Point { x: 55, ..clone(p) } // Clone at the move site to keep 'p' available
    print(str_len(p.tag))
    print(q.x)
}

struct Pair { a: Vec<Int>, b: Str }

fn main() {
    let s = Pair { a: push(push(vec(), 1), 2), b: "hello" }
    let Pair { a, b } = s.clone()
    print(len(a))
    print(str_len(b))
    print(str_len(s.b))
}

fn main() {
    let o = Some(concat("ab", "cd"));
    match o {
        Some(s) => print(str_len(s) * 5),
        None => print(0),
    }
    match clone(o) {
        Some(s) => print(str_len(s) * 6),
        None => print(0),
    }
}

fn main() {
    let s = "ab"
    print(str_len(s) * 10)
    let i = 0
    let total = 0
    while i < 3 {
        let t = s.clone(); // Clone the value before using it in the loop
        total = total + str_len(t) * 5
        i = i + 1
    }
    print(total)
}

fn total(v: Vec<Int>, flag: Bool) -> Int {
    let w = v.clone(); // clone before moving
    if flag {
        return len(w) * 10;
    }
    let u = push(v, 3);
    len(u) * 20
}

fn main() {
    print(total(push(push(vec(), 1), 2), true));
    print(total(push(push(vec(), 1), 2), false));
}

fn f(o: Option<Vec<Int>>) -> Option<Int> {
    let v = o?;
    let w = o?; // Fix by cloning at the earlier site or reordering
    Some(len(v) * 10 + len(w))
}

fn main() {
    match f(Some(push(push(vec(), 1), 2))) {
        Some(n) => print(n),
        None => print(0),
    }
    match f(None) {
        Some(n) => print(n),
        None => print(99),
    }
}

fn main() {
    let s = "hello"
    let n = 5;
    if n > 3 {
        if n > 4 {
            let t = clone(s);
            print(str_len(t) * 4);
        }
        print(str_len(s) * 6);
    }
}

fn main() {
    let mut acc = range(0, 10);
    print(len(acc));
    for i in 0..3 {
        let grown = push(&mut acc, i); // Reassign the variable inside the loop
    }
    print(len(acc));
}

fn main() {
    let s = "abcdefghij";
    print(str_len(s.clone()));
    let t = concat(s.clone(), s);
    print(str_len(t));
}

fn main() {
    let s = "hello world";
    let n = 42;
    let t = s.clone(); // Clone the string to avoid ownership issues
    print(str_len(t));
    if n > 3 {
        print(str_len(s)); // Use the original string now that it's cloned
    }
}

fn main() {
    let v = range(0, 10);
    print(len(v));
    let mut total = 0;
    for x in v {
        if x > 4 {
            let w = push(v.clone(), x);
            total = len(w);
            break;
        }
    }
    print(total);
}
